t = int(input())
i = 0
while i < t:
	k = []
	n = int(input())
	l = list(map(int, input().split()))
	for j in l:
		if j % 2 != 0:
			k.append(j)
	odd = len(k)
	if odd == 0:
		print(0)
	elif odd == 1:
		print(0)
	elif odd > 1 and odd % 2 == 0:
		print(odd // 2)
	elif odd > 1 and odd % 2 != 0:
		print((odd - 1) // 2)
	i += 1
